import React, { Component } from "react";
import "react-loader-spinner/dist/loader/css/react-spinner-loader.css";
// import Loader from "react-loader-spinner";
import { FormattedMessage } from "react-intl";
import { Progress } from "react-sweet-progress";
import "react-sweet-progress/lib/style.css";

// Redux
import { connect } from "react-redux";
import { bindActionCreators } from "redux";
import { handleFileUpload, refreshUpload } from "../../actions/utils";

// components
import { Col, Row, Card, Label, Input, Alert } from "reactstrap";

// styles
import "./FileUpload.css";

class FileUpload extends Component {
	constructor (props) {
		super(props);
		this.state = {
			selectedItems  : [],
			uploading      : false,
			uploadProgress : 0,
			toggle         : false,
		};
	}

	componentDidUpdate (prevState, prevProps) {
		if (this.props.uploaded && this.props.uploaded !== this.state.toggle) {
			return this.setState({ toggle: !this.state.toggle });
		}
	}

	handleDragOver = (e) => {
		e.preventDefault();
	};

	handleDragLeave = (e) => {
		e.preventDefault();
	};

	handleDrop = (e) => {
		e.preventDefault();
		e.stopPropagation(); //stops downloading on drop
		const uploadItems = [ ...e.dataTransfer.files ];

		this.setState({
			uploading      : true,
			uploadProgress : 100 / uploadItems,
			selectedItems  : uploadItems,
		});

		let i = 0;
		while (i < uploadItems.length) {
			const data = new FormData();
			data.append("file", e.dataTransfer.files[i]);
			this.props.handleFileUpload(data);
			i++;
		}
		document.getElementById("file").value = ""; // clears fileList to allow upload of the same files more than once.
	};

	refresh = () => {
		this.setState({
			uploadProgress : 0,
			selectedItems  : [],
			uploading      : false,
		});
	};

	toggle = () => {
		this.props.refreshUpload();
		this.setState({
			toggle         : !this.toggle,
			uploadProgress : 0,
		});
	}; // close modal

	handleChange = (e) => {
		const uploadItems = [ ...e.target.files ];
		this.setState({
			uploading     : true,
			selectedItems : uploadItems,
		});
		let i = 0;
		while (i < uploadItems.length) {
			const data = new FormData();
			data.append("file", e.target.files[i]);
			this.props.handleFileUpload(data);
			i++;
		}
		document.getElementById("file").value = ""; // clears fileList to allow upload of the same files more than once.
	};

	render () {
		return (
			<section className='contaner-fluid'>
				<Row>
					<Card className={"col-12 vh-100 d-flex justify-content-center align-items-center"}>
						<Col
							id='upload-container'
							className='col-10 vh-100 d-flex flex-column justify-content-center align-items-center'
						>
							<section
								id='drop-zone'
								onDrop={this.handleDrop}
								onDragOver={this.handleDragOver}
								onDragLeave={this.onDragLeave}
							>
								<div className='col-6 mx-auto'>
									<Input
										type='file'
										name='file'
										id='file'
										className='inputfile'
										multiple
										onChange={this.handleChange}
									/>
									<Label for='file'>
										<i className='fa fa-cloud-upload' aria-hidden='true' />
									</Label>
								</div>

								{!this.state.uploading && (
									<h6 className='text-center text-danger my-2'>
										<FormattedMessage
											id='Choose Your File Or Drag It Here.'
											defaultMessage='Choose Your File Or Drag It Here.'
										/>
									</h6>
								)}
							</section>

							{!this.props.isError &&
							this.state.uploading && (
								<div className='w-50 mt-5'>
									<Progress
										percent={this.props.uploadProgress ? Math.round(this.props.uploadProgress) : 0}
										status='success'
									/>

									<div className='d-flex justify-content-center align-items-center'>
										<button
											onClick={this.refresh}
											type='button'
											className='btn btn-success btn-md m-2'
										>
											Refresh
										</button>
									</div>
								</div>
							)}

							{this.props.isError && (
								<Alert
									className='w-50 mt-4 mx-auto text-center'
									color='danger'
									isOpen={this.state.toggle}
									toggle={this.toggle}
								>
									{
										<FormattedMessage
											id='Error: Your file upload failed. Please refresh and tryagain!'
											defaultMessage='Error: Your file upload failed. Please refresh and tryagain'
										/>
									}
								</Alert>
							)}
						</Col>
					</Card>
				</Row>
			</section>
		);
	}
}

const mapStateToProps = (state, ownProps) => {
	return {
		fileUpload     : state.utils.fileUpload,
		uploadStatus   : state.utils.uploadStatus,
		uploaded       : state.utils.uploaded,
		isError        : state.utils.isError,
		uploadProgress : state.utils.uploadProgress,
	};
};

const mapDispatchToProps = (dispatch) => {
	return bindActionCreators(
		{
			handleFileUpload,
			refreshUpload,
		},
		dispatch,
	);
};

export default connect(mapStateToProps, mapDispatchToProps)(FileUpload);
